def delete(self, key):
        cur = self.head
        while cur:
            if cur.data == key and cur == self.head:
                # 情况 1: 删除节点是 链表的唯一节点，即头节点
                if not cur.next:
                    cur = None 
                    self.head = None
                    return
            cur = cur.next
